import{_ as e,c as n,o as i,a0 as r}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Einführung in das mentale Spiel – Teilnehmerleitfaden","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/de/participant-guide.md","filePath":"public/downloads/de/participant-guide.md"}');const a=e({name:"public/downloads/de/participant-guide.md"},[["render",function(e,t,a,l,s,h){return i(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="einfuhrung-in-das-mentale-spiel-–-teilnehmerleitfaden" tabindex="-1">Einführung in das mentale Spiel – Teilnehmerleitfaden <a class="header-anchor" href="#einfuhrung-in-das-mentale-spiel-–-teilnehmerleitfaden" aria-label="Permalink to &quot;Einführung in das mentale Spiel – Teilnehmerleitfaden&quot;">​</a></h1><p><strong>Pétanque-Akademie</strong><em>Entwicklung von Spitzenspielern</em></p><hr><h2 id="willkommen" tabindex="-1">Willkommen <a class="header-anchor" href="#willkommen" aria-label="Permalink to &quot;Willkommen&quot;">​</a></h2><p>Heute lernen Sie praktische mentale Spieltechniken, um Ihre Pétanque-Leistung zu verbessern.</p><h3 id="was-sie-lernen-werden" tabindex="-1">Was Sie lernen werden <a class="header-anchor" href="#was-sie-lernen-werden" aria-label="Permalink to &quot;Was Sie lernen werden&quot;">​</a></h3><ul><li>Warum mentales Training für Spitzenspieler wichtig ist</li><li>Der Unterschied zwischen „technischem Modus“ und „Flow-Modus“</li><li>Wie Sie Ihren inneren Kritiker erkennen und mit ihm umgehen können</li><li>Einfache Techniken zur Druckbewältigung</li><li>Eine grundlegende Vorbereitungsroutine</li></ul><hr><h2 id="die-zone-stromungszustand" tabindex="-1">Die Zone / Strömungszustand <a class="header-anchor" href="#die-zone-stromungszustand" aria-label="Permalink to &quot;Die Zone / Strömungszustand&quot;">​</a></h2><h3 id="was-ist-flow" tabindex="-1">Was ist Flow? <a class="header-anchor" href="#was-ist-flow" aria-label="Permalink to &quot;Was ist Flow?&quot;">​</a></h3><p>Flow ist jener magische Zustand, in dem:</p><ul><li>Alles fühlt sich mühelos an</li><li>Die Zeit scheint langsamer zu vergehen</li><li>Du denkst nicht nach, du spielst einfach.</li><li>Ihre Technik wird perfekt ausgeführt</li></ul><h3 id="zwei-denkweisen" tabindex="-1">Zwei Denkweisen <a class="header-anchor" href="#zwei-denkweisen" aria-label="Permalink to &quot;Zwei Denkweisen&quot;">​</a></h3><p><strong>Planungsmodus (Analytisch)</strong></p><ul><li>Analyse des Geländes</li><li>Ihre Strategie auswählen</li><li>Die richtige Aufnahme auswählen</li><li>Risikobewertung</li></ul><p><strong>Ausführungsmodus (Ablauf)</strong></p><ul><li>Vertraue deinem Körper</li><li>Nicht an die Technik denken</li><li>Fokus auf den gegenwärtigen Moment</li><li>Automatische Ausführung</li></ul><h3 id="der-schalter" tabindex="-1">Der Schalter <a class="header-anchor" href="#der-schalter" aria-label="Permalink to &quot;Der Schalter&quot;">​</a></h3><p>Die Schlüsselkompetenz: <strong>Wechsel von der Planungs- zur Ausführungsphase</strong></p><p><strong>Vor dem Schuss:</strong> Analysieren, planen, entscheiden <strong>Während der Aufnahme:</strong> Vertrauen, Flow, Ausführung</p><hr><h2 id="der-innere-kritiker-vs-der-innere-coach" tabindex="-1">Der innere Kritiker vs. der innere Coach <a class="header-anchor" href="#der-innere-kritiker-vs-der-innere-coach" aria-label="Permalink to &quot;Der innere Kritiker vs. der innere Coach&quot;">​</a></h2><h3 id="dein-innerer-kritiker-sagt" tabindex="-1">Dein innerer Kritiker sagt: <a class="header-anchor" href="#dein-innerer-kritiker-sagt" aria-label="Permalink to &quot;Dein innerer Kritiker sagt:&quot;">​</a></h3><ul><li>&quot;Das war furchtbar!&quot;</li><li>&quot;Unter Druck machst du immer Fehler.&quot;</li><li>&quot;Alle sehen dir beim Scheitern zu.&quot;</li><li>&quot;Du bist nicht gut genug.&quot;</li></ul><h3 id="dein-innerer-coach-sagt" tabindex="-1">Dein innerer Coach sagt: <a class="header-anchor" href="#dein-innerer-coach-sagt" aria-label="Permalink to &quot;Dein innerer Coach sagt:&quot;">​</a></h3><ul><li>Was kann ich daraus lernen?</li><li>&quot;Nächster Versuch, Neuanfang&quot;</li><li>„Diesen Wurf habe ich schon einmal gemacht.“</li><li>„Vertraue dem Prozess.“</li></ul><h3 id="umstrukturierungsubung" tabindex="-1">Umstrukturierungsübung <a class="header-anchor" href="#umstrukturierungsubung" aria-label="Permalink to &quot;Umstrukturierungsübung&quot;">​</a></h3><p>Wenn du deinen inneren Kritiker bemerkst:</p><ol><li><strong>Pause</strong> – Den kritischen Gedanken erkennen</li><li><strong>Umformulierung</strong> – Was würde Ihr Trainer sagen?</li><li><strong>Zurücksetzen</strong> – Dreimal tief durchatmen</li><li><strong>Neu fokussieren</strong> – Nächste Aufnahme</li></ol><hr><h2 id="praktische-werkzeuge" tabindex="-1">Praktische Werkzeuge <a class="header-anchor" href="#praktische-werkzeuge" aria-label="Permalink to &quot;Praktische Werkzeuge&quot;">​</a></h2><h3 id="_3-atemzug-reset" tabindex="-1">3-Atemzug-Reset <a class="header-anchor" href="#_3-atemzug-reset" aria-label="Permalink to &quot;3-Atemzug-Reset&quot;">​</a></h3><p>Verwenden Sie dies nach Fehlern oder wenn Sie unter Druck stehen:</p><ol><li><strong>Atemzug 1:</strong> Nehmen Sie die Anspannung wahr (wo spüren Sie sie?)</li><li><strong>Atemzug 2:</strong> Die Anspannung lösen (loslassen)</li><li><strong>Atemzug 3:</strong> Konzentriere dich wieder auf das Jetzt (diese Aufnahme, diesen Moment)</li></ol><h3 id="routine-vor-der-impfung" tabindex="-1">Routine vor der Impfung <a class="header-anchor" href="#routine-vor-der-impfung" aria-label="Permalink to &quot;Routine vor der Impfung&quot;">​</a></h3><p>Schaffen Sie Beständigkeit mit einer einfachen Routine:</p><ol><li><strong>Visualisieren Sie</strong> – Stellen Sie sich die Aufnahme in Ihrem Kopf vor</li><li><strong>Atmen</strong> – Ein tiefer Atemzug</li><li><strong>Anker</strong> – Berühren Sie Ihre Kugel, spüren Sie das Gewicht</li><li><strong>Ausführen</strong> – Vertrauen und werfen</li></ol><h3 id="fehlerkorrekturprotokoll" tabindex="-1">Fehlerkorrekturprotokoll <a class="header-anchor" href="#fehlerkorrekturprotokoll" aria-label="Permalink to &quot;Fehlerkorrekturprotokoll&quot;">​</a></h3><p>Nach einem missglückten Schuss:</p><ol><li><strong>Anerkennen</strong> – „Das ist nicht wie geplant verlaufen.“</li><li><strong>Entspannung</strong> – Physischer Neustart (abschütteln, gehen)</li><li><strong>Neufokus</strong> – „Der nächste Schuss ist eine neue Chance“</li><li><strong>Ausführen</strong> – Vertraue deiner Routine.</li></ol><hr><h2 id="ihr-aktionsplan" tabindex="-1">Ihr Aktionsplan <a class="header-anchor" href="#ihr-aktionsplan" aria-label="Permalink to &quot;Ihr Aktionsplan&quot;">​</a></h2><h3 id="diese-woche" tabindex="-1">Diese Woche <a class="header-anchor" href="#diese-woche" aria-label="Permalink to &quot;Diese Woche&quot;">​</a></h3><p>Wähle EINE Technik zum Üben aus:</p><ul><li>[ ] 3-Atemzüge: Nach jedem Fehler zurücksetzen</li><li>[ ] Vorwurf-Routine bei jedem Wurf</li><li>[ ] Pro Sitzung einen Gedanken des inneren Kritikers umformulieren</li><li>[ ] Üben Sie den Wechsel vom Planungs- zum Ausführungsmodus</li></ul><h3 id="verfolge-deinen-fortschritt" tabindex="-1">Verfolge deinen Fortschritt <a class="header-anchor" href="#verfolge-deinen-fortschritt" aria-label="Permalink to &quot;Verfolge deinen Fortschritt&quot;">​</a></h3><p>Beachten:</p><ul><li>Wann fühlst du dich am meisten im Flow?</li><li>Was triggert deinen inneren Kritiker?</li><li>Welche Technik hilft Ihnen am meisten?</li><li>Wie verändert sich Ihre Leistung?</li></ul><hr><h2 id="ressourcen-amp-nachste-schritte" tabindex="-1">Ressourcen &amp; Nächste Schritte <a class="header-anchor" href="#ressourcen-amp-nachste-schritte" aria-label="Permalink to &quot;Ressourcen &amp;amp; Nächste Schritte&quot;">​</a></h2><h3 id="weiterlernen" tabindex="-1">Weiterlernen <a class="header-anchor" href="#weiterlernen" aria-label="Permalink to &quot;Weiterlernen&quot;">​</a></h3><ul><li><strong>Die Zone</strong> – Tiefer Einblick in Flow-Zustände</li><li><strong>Mentale Stärke</strong> – Fortschrittliches Stressmanagement</li><li><strong>Zielvorlage</strong> – Strukturieren Sie Ihre Entwicklung</li><li><strong>Tagebuchvorlage</strong> – Verfolge deinen Fortschritt</li></ul><h3 id="taglich-uben" tabindex="-1">Täglich üben <a class="header-anchor" href="#taglich-uben" aria-label="Permalink to &quot;Täglich üben&quot;">​</a></h3><ul><li>5 Minuten achtsames Atmen</li><li>Erfolgreiche Aufnahmen visualisieren</li><li>Übe deine Vorbereitungsroutine vor dem Wurf.</li><li>Negative Gedanken umformulieren</li></ul><hr><h2 id="wichtigste-erkenntnisse" tabindex="-1">Wichtigste Erkenntnisse <a class="header-anchor" href="#wichtigste-erkenntnisse" aria-label="Permalink to &quot;Wichtigste Erkenntnisse&quot;">​</a></h2><ol><li><strong>Der Flow-Zustand ist zugänglich</strong> – Sie können lernen, ihn regelmäßiger zu erreichen.</li><li><strong>Deine innere Stimme zählt</strong> – Coache dich selbst, kritisiere dich nicht.</li><li><strong>Einfache Hilfsmittel wirken:</strong> – 3 Atemzüge, eine Routine, ein Neustart</li><li><strong>Übung macht den Meister</strong> – Mentale Fähigkeiten müssen genauso trainiert werden wie technische Fähigkeiten.</li></ol><hr><p><strong>Wichtig:</strong> Mentales Training hat nichts mit positivem Denken zu tun. Es geht um praktische Techniken, die Ihnen helfen, unter Druck Ihre beste Leistung abzurufen.</p><hr><p><em>Weitere Informationen finden Sie auf carreau.app</em><em>Pétanque Academy – Elite-Spielerentwicklung</em></p>',61)])])}]]);export{t as __pageData,a as default};
